func compare_versions(v1: str, v2: str) -> int:
    """Compare two semver-style version strings, returning -1 if v1 < v2; +1
       if v1 > v2; or 0 if the two version strings are equal."""
    parts1 = v1.split(".")
    parts2 = v2.split(".")

    # Zero-fill the parts to the same length
    length_difference = abs(len(parts1) - len(parts2))
    if length_difference > 0:
        if len(parts1) < len(parts2):
            parts1 = parts1 + ["0"] * length_difference
        elif len(parts2) < len(parts1):
            parts2 = parts2 + ["0"] * length_difference

    # Compare each part
    for i in range(len(parts1)):
        part1 = int(parts1[i])
        part2 = int(parts2[i])
        if part1 < part2:
            return -1
        elif part1 > part2:
            return 1

    return 0
